/// Parses a hexadecimal string into bytes.
fn unhex(text: &str) -> Vec<u8> {
    text.as_bytes()
        .chunks(2)
        .map(|pair| {
            let hi = (pair[0] as char).to_digit(16).unwrap();
            let lo = (pair[1] as char).to_digit(16).unwrap();
            ((hi << 4) | lo) as u8
        })
        .collect()
}

/// Builds the message described by a fixture.
fn build(mti: &str, fields: &[(u8, &str)]) -> Message {
    let mut msg = Message::new(mti).unwrap();
    for (field, value) in fields {
        msg.set(*field, value).unwrap();
    }
    msg
}

#[test]
fn encoding_matches_the_reference_bytes_exactly() {
    let spec = default_ascii();
    for (mti, fields, expected) in CASES {
        let msg = build(mti, fields);
        let encoded = msg
            .encode(&spec)
            .unwrap_or_else(|e| panic!("{mti} {fields:?}: {e}"));
        assert_eq!(
            encoded,
            unhex(expected),
            "{mti} {fields:?} encoded to {}",
            encoded
                .iter()
                .map(|b| format!("{b:02X}"))
                .collect::<String>()
        );
    }
}

#[test]
fn decoding_the_reference_bytes_recovers_the_fields() {
    let spec = default_ascii();
    for (mti, fields, expected) in CASES {
        let decoded = Message::decode(&unhex(expected), &spec)
            .unwrap_or_else(|e| panic!("{mti} {expected}: {e}"));
        assert_eq!(decoded.mti(), *mti);
        for (field, value) in *fields {
            assert_eq!(decoded.get(*field), Some(*value), "{mti} field {field}");
        }
        assert_eq!(decoded.len(), fields.len(), "{mti} {fields:?}");
    }
}

#[test]
fn every_fixture_survives_a_round_trip() {
    let spec = default_ascii();
    for (mti, fields, _) in CASES {
        let msg = build(mti, fields);
        let bytes = msg.encode(&spec).unwrap();
        let back = Message::decode(&bytes, &spec).unwrap();
        assert_eq!(back, msg, "{mti} {fields:?}");
    }
}

#[test]
fn the_message_type_indicator_comes_back_unchanged() {
    let spec = default_ascii();
    for (mti, fields, _) in CASES {
        let bytes = build(mti, fields).encode(&spec).unwrap();
        let back = Message::decode(&bytes, &spec).unwrap();
        assert_eq!(back.mti(), *mti);
    }
}
